class TimingLoggingInterceptor implements HandlerInterceptor {

    public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) {
        req.setAttribute("startTime", System.nanoTime());
        return true;
    }

    public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mv) {
        // PO metodzie kontrolera, PRZED renderowaniem widoku (rzadko uzywane w REST API)
    }

    public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception ex) {
        long elapsed = (System.nanoTime() - (long) req.getAttribute("startTime")) / 1_000_000;
        System.out.println("Zadanie trwalo: " + elapsed + "ms");
    }
}

public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler)
        throws IOException {
    String apiKey = request.getHeader("X-Api-Key");
    if (apiKey == null || !apiKey.equals("tajny-klucz")) {
        response.setStatus(401);
        response.getWriter().write("Brak lub nieprawidlowy X-Api-Key");
        return false; // PRZERYWA lancuch, kontroler NIGDY nie zostaje wywolany
    }
    return true;
}
